@section('content')<div x-data="usersIndex()" x-init="init()" x-cloak><div class="mb-7 flex items-end justify-between"><div><p class="text-sm text-slate-600">Kelola akses Admin dan Operator</p><h2 class="mt-1 text-2xl font-semibold text-navy-900">Pengguna internal</h2></div><a href="{{ route('users.create') }}" class="action-button-primary">+ Tambah pengguna</a></div><div x-show="notice" class="mb-4 rounded-xl border border-teal-200 bg-teal-50 px-4 py-3 text-sm text-teal-800" x-text="notice"></div><div x-show="error" class="mb-4 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700" x-text="error"></div><section class="overflow-hidden rounded-2xl border border-border bg-white shadow-sm"><div class="border-b border-border px-5 py-4"><h3 class="font-semibold text-navy-900">Daftar pengguna</h3><p class="mt-1 text-xs text-slate-500" x-text="`${users.length} pengguna`"></p></div><div class="overflow-x-auto"><table class="w-full min-w-[700px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-5 py-3">Nama</th><th class="px-5 py-3">Email</th><th class="px-5 py-3">Role</th><th class="px-5 py-3 text-right">Aksi</th></tr></thead><tbody class="divide-y divide-border"><template x-for="user in users" :key="user.id"><tr><td class="px-5 py-4 font-semibold text-navy-900" x-text="user.name"></td><td class="px-5 py-4 text-slate-600" x-text="user.email"></td><td class="px-5 py-4"><span class="rounded-full bg-teal-100 px-2.5 py-1 text-xs font-medium uppercase text-teal-800" x-text="user.role"></span></td><td class="px-5 py-4 text-right"><button @click="remove(user)" class="action-link text-red-600">Hapus</button></td></tr></template></tbody></table></div><div x-show="!loading&&!users.length" class="px-5 py-16 text-center text-sm text-slate-500">Belum ada pengguna.</div></section></div><script>function usersIndex(){return{users:[],loading:true,error:'',notice:new URLSearchParams(location.search).get('success')?'Pengguna berhasil dibuat.':'',async init(){if(this.$store.auth.role!=='admin'){location.href='/dashboard';return}try{this.users=(await window.axios.get('/api/admin/users')).data||[]}catch(e){this.error=e.response?.data?.message||'Gagal memuat pengguna.'}finally{this.loading=false}},async remove(u){if(!confirm(`Hapus pengguna ${u.name}?`))return;try{await window.axios.delete(`/api/admin/users/${u.id}`);this.notice='Pengguna berhasil dihapus.';await this.init()}catch(e){this.error=e.response?.data?.message||'Gagal menghapus pengguna.'}}}}</script>@endsection
